float sdSphere(vec3 p, float s){
    return length(p) - s;
}

float sdBox(vec3 p, vec3 b){
    vec3 q = abs(p) - b;
    return length(max(q,0.0)) + min(max(q.x, max(q.y, q.z)), 0.0);
}

float smin(float a, float b, float k) {
    float h = max(k-abs(a-b),0.0)/k;
    return min(a,b) - h*h*h*k*(1.0/6.0);
}

float map(vec3 p){
    vec3 spherePos = vec3(sin(iTime)* 3.0, 0., 0.);
    float sphere = sdSphere(p - spherePos, .3);

    float box = sdBox(p, vec3(.75));

    float ground = p.y + 0.95;

    return smin(ground, smin(sphere, box,2.), .2);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
        // 1. Init
        vec2 uv = (fragCoord * 2.0 - iResolution.xy)/iResolution.y;        

        float fov = 1.4; // How wide the rays spread out

        vec3 rayOrigin = vec3(0, 0, -3);
        vec3 rayDirection = normalize(vec3(uv * fov, 1.0));
        vec3 col = vec3(0);

        float t = 0.0; // Total distance traveled

        // 2. Ray Marching
        for (int i = 0; i < 80; i++) {
                vec3 p = rayOrigin + rayDirection * t; // current position along the ray
                float d = map(p); // current distance to the closest object

                t += d;

                if(d < .001) break; // Break Ray March if the distance to the closest object is very small
                if(t>100.) break; // Break if Ray has travelled too far

        }

        col = vec3(t * .05);

        fragColor = vec4(col, 1);


}
